<script setup lang="ts">import{onMounted,ref}from'vue';import{events,err,isDemo,type Evidence}from'./api';import{useRoute}from'vue-router';const route=useRoute(),item=ref<any>(),evidence=ref<Evidence[]>([]),error=ref<any>(),open=ref<string>();const safe=(u:string)=>/^https?:\/\//i.test(u);onMounted(async()=>{try{item.value=await events.one(String(route.params.id));evidence.value=await events.evidence(String(route.params.id))}catch(e){error.value=err(e)}});</script><template><p><RouterLink :to="`/${isDemo()?'?demo=1':''}`">← 返回事件</RouterLink></p><div v-if="error" class="card error" role="alert">{{error.message}}</div><article v-else-if="item" class="card"><p class="meta">{{item.event_date||'日期未知'}} · {{item.date_precision}}</p><h1>{{item.title_zh}}</h1><p>{{item.summary_zh}}</p><h2>相关实体</h2><p class="row"><span v-for="e in item.entities" class="pill">{{e}}</span></p><h2>来源与摘录</h2><p v-if="isDemo()" class="demo">以下摘录为合成演示，不是系统保存的原文。</p><p v-if="!item.evidence_count" class="meta">此事件没有关联证据。</p><div v-for="x in (item.evidence_count ? evidence : [])" :key="x.id" class="card"><button class="focus" :aria-expanded="open===x.id" @click="open=open===x.id?undefined:x.id">{{open===x.id?'收起':'展开'}}摘录：{{x.title}}</button><blockquote v-if="open===x.id">{{x.quote_text}}<footer class="meta">版本 {{x.article_version_id}} · 段落 {{x.paragraph_id}}</footer></blockquote><a v-if="safe(x.source_url)" :href="x.source_url" target="_blank" rel="noopener">打开来源</a><span v-else class="meta">来源地址无效</span></div></article><p v-else aria-live="polite">正在加载详情…</p></template>


